interface BashSandboxState {
  originalCommand: string;
  wrappedCommand: string;
  sessionID: string | undefined;
  policyDir: string;
  port: number | null;
  proxyToken: string | null;
  stop: (() => Promise<void>) | null;
  trapServer: ReturnType<typeof createServer> | null;
  trapServerPort: number | null;
  trapStanzas: string[];
  tuiConnected: boolean;
  shellID?: string;
  shellExited?: boolean;
  background?: boolean;
}

type SandboxPermissionKind = 'read' | 'write' | 'domain';

interface SandboxPermissionDecision {
  status: 'allow' | 'ask' | 'deny';
  kind: SandboxPermissionKind;
  resource: string;
  message: string;
}

type ToastVariant = 'info' | 'success' | 'warning' | 'error';

const REQUIRED_LANDSTRIP_VERSION = '0.17.0';
const SUPPORTED_PLATFORMS = new Set<NodeJS.Platform>(['linux', 'darwin', 'win32']);

function evaluateReadPermission(
  path: string,
  config: SandboxConfig,
  baseDirectory: string,
  effectiveAllowRead: string[],
): SandboxPermissionDecision {
  const filePath = canonicalizePath(path, baseDirectory);
  const decision = evaluateReadAccess(filePath, config.filesystem, {
    baseDirectory,
    allowReadOverrides: effectiveAllowRead,
    requireAllowMatch: true,
  });

  if (decision === 'deny') {
    return {
      status: 'deny',
      kind: 'read',
      resource: filePath,
      message: `Sandbox: read access denied for "${filePath}" (denyReadAlways).`,
    };
  }

  if (decision === 'allow') {
    return { status: 'allow', kind: 'read', resource: filePath, message: '' };
  }

  return {
    status: 'ask',
    kind: 'read',
    resource: filePath,
    message: `Sandbox: read access requires approval for "${filePath}".`,
  };
}

function evaluateWritePermission(
  path: string,
  config: SandboxConfig,
  baseDirectory: string,
  effectiveAllowWrite: string[],
): SandboxPermissionDecision {
  const filePath = canonicalizePath(path, baseDirectory);
  const decision = evaluateWriteAccess(filePath, config.filesystem, {
    baseDirectory,
    allowWriteOverrides: effectiveAllowWrite,
  });

  if (decision === 'deny') {
    return {
      status: 'deny',
      kind: 'write',
      resource: filePath,
      message: `Sandbox: write access denied for "${filePath}" (denyWriteAlways).`,
    };
  }

  if (decision === 'allow') {
    return { status: 'allow', kind: 'write', resource: filePath, message: '' };
  }

  return {
    status: 'ask',
    kind: 'write',
    resource: filePath,
    message: `Sandbox: write access requires approval for "${filePath}".`,
  };
}

function evaluateDomainPermission(
  domain: string,
  config: SandboxConfig,
): SandboxPermissionDecision {
  const decision = evaluateDomainAccess(domain, config.network);

  if (decision === 'deny') {
    return {
      status: 'deny',
      kind: 'domain',
      resource: domain,
      message: `Sandbox: network access denied for "${domain}" (is blocked by network.deniedDomains).`,
    };
  }

  if (decision === 'allow') {
    return { status: 'allow', kind: 'domain', resource: domain, message: '' };
  }

  return {
    status: 'ask',
    kind: 'domain',
    resource: domain,
    message: `Sandbox: network access requires approval for "${domain}" (not in network.allowedDomains).`,
  };
}

function evaluateCommandDomains(
  command: string,
  config: SandboxConfig,
): SandboxPermissionDecision[] {
  if (config.network.allowNetwork) return [];
  return extractDomainsFromCommand(command).map((domain) =>
    evaluateDomainPermission(domain, config),
  );
}

function writePolicyFile(
  config: SandboxConfig,
  baseDirectory: string,
  proxyPort: number | null,
): { dir: string; path: string } {
  return writeLandstripPolicyFile(
    buildLandstripPolicy({
      network: config.network,
      filesystem: config.filesystem,
      macos: config.macos,
      windows: config.windows,
      baseDirectory,
      httpProxyPort: proxyPort,
    }),
    'opencode-landstrip-',
  );
}

function proxyEnv(
  port: number | null,
  proxyToken?: string | null,
): Record<string, string> | undefined {
  if (port === null) return undefined;
  return createProxyEnvironment(port, { token: proxyToken }) as Record<string, string>;
}

function shellArgs(shell: string, command: string): string[] {
  const name = basename(shell).toLowerCase();
  if (name.includes('fish')) return [shell, '-c', command];
  return [shell, '-lc', command];
}

// Start a local TCP server that landstrip connects its trap fd to. Traps are
// handled in-process: query traps are answered immediately against the active
// config, and info traps are collected for post-execution error reporting.
function startTrapServer(
  effectiveAllowRead: string[],
  effectiveAllowWrite: string[],
  denyRead: string[],
  denyWrite: string[],
  baseDirectory: string,
  denyReadAlways: string[] = [],
  denyWriteAlways: string[] = [],
): Promise<{ server: ReturnType<typeof createServer>; port: number; trapStanzas: string[] }> {
  const trapStanzas: string[] = [];
  const server = createServer((trapSocket) => {
    trapSocket.setEncoding('utf8');
    let buffer = '';
    const handleStanza = (stanza: string): void => {
      if (stanza.trim().length === 0) return;
      const trap = parseTrapStanza(stanza);
      if (trap && isQueryTrap(trap)) {
        const queryId = trap.query_id;
        if (trap.kind === 'filesystem') {
          const path = canonicalizePath(trap.path, baseDirectory);
          const operation = trap.operation;
          const allowed =
            operation === 'read'
              ? evaluateReadAccess(
                  path,
                  { allowRead: effectiveAllowRead, denyRead, denyReadAlways },
                  { baseDirectory, requireAllowMatch: true },
                ) === 'allow'
              : evaluateWriteAccess(
                  path,
                  { allowWrite: effectiveAllowWrite, denyWrite, denyWriteAlways },
                  { baseDirectory },
                ) === 'allow';
          trapSocket.write(controlResponseStanza(queryId, allowed ? 'allow' : 'deny'));
        } else {
          trapSocket.write(controlResponseStanza(queryId, 'deny'));
        }
      } else {
        trapStanzas.push(`${stanza}\n\n`);
      }
    };
    trapSocket.on('data', (data: string) => {
      buffer += data;
      let boundary = buffer.indexOf('\n\n');
      while (boundary !== -1) {
        const stanza = buffer.slice(0, boundary);
        buffer = buffer.slice(boundary + 2);
        boundary = buffer.indexOf('\n\n');
        handleStanza(stanza);
      }
    });
    trapSocket.once('end', () => {
      const rest = buffer.trim();
      buffer = '';
      if (rest.length > 0) handleStanza(rest);
    });
    trapSocket.on('error', () => {});
  });

  return new Promise((resolve, reject) => {
    server.on('error', reject);
    server.listen(0, '127.0.0.1', () => {
      server.removeListener('error', reject);
      const address = server.address() as AddressInfo;
      resolve({ server, port: address.port, trapStanzas });
    });
  });
}

function buildWrappedCommand(
  policyPath: string,
  shell: string,
  command: string,
  trapPort: number | null,
  sessionID?: string,
): string {
  const baseArgs = ['run', '-p', policyPath, '--', ...shellArgs(shell, command)];
  const plain = quoteShell([landstripBinaryPath(), ...baseArgs]);
  if (trapPort === null) return plain;

  // Open fd 3 before landstrip starts the command. The wrapper must never use
  // the command's exit status to select a fallback: by then the command may
  // already have changed the workspace. A failed socket setup therefore stops
  // without invoking landstrip, while every started command runs exactly once.
  const trapped = quoteShell([
    landstripBinaryPath(),
    'run',
    '--trap',
    '3',
    '-p',
    policyPath,
    '--',
    ...shellArgs(shell, command),
  ]);
  const identifySession = sessionID
    ? ` && printf '%s' ${quoteShell([trapSessionHelloStanza(sessionID)])} >&3`
    : '';
  const openTrap = `exec 3<>/dev/tcp/127.0.0.1/${trapPort}${identifySession} && exec "$@"`;
  return quoteShell(['bash', '-c', openTrap, 'bash']) + ` ${trapped}`;
}

function isGeneratedWrappedCommand(command: string): boolean {
  return (
    // `.includes` rather than `.startsWith`: the query-response form prefixes
    // the landstrip invocation with a small bash fd-setup wrapper.
    command.includes(`${quoteShell([landstripBinaryPath()])} `) &&
    command.includes(` ${quoteShell(['-p'])} `) &&
    command.includes('opencode-landstrip-')
  );
}

function splitShellQuotedArgs(command: string): string[] {
  // Preserve variable references literally; never read the host environment.
  const args = parseShell(command, (name) => `$${name}`);
  return args.map((arg) => {
    if (typeof arg !== 'string') {
      throw new Error('Unexpected shell operator in generated landstrip command');
    }
    return arg;
  });
}

function extractOriginalCommand(wrappedCommand: string): string | null {
  const args = splitShellQuotedArgs(wrappedCommand);
  const pIdx = args.indexOf('-p');
  const flagIdx = args.findIndex((arg, i) => i > pIdx && (arg === '-lc' || arg === '-c'));
  if (flagIdx === -1) return null;
  return args.slice(flagIdx + 1).join(' ');
}
function extractPatchPaths(patchText: string): string[] {
  const paths: string[] = [];

  for (const line of patchText.split(/\r?\n/)) {
    const fileMatch = line.match(/^\*\*\* (?:Add|Update|Delete) File: (.+)$/);
    if (fileMatch?.[1]) {
      paths.push(fileMatch[1].trim());
      continue;
    }

    const moveMatch = line.match(/^\*\*\* Move to: (.+)$/);
    if (moveMatch?.[1]) paths.push(moveMatch[1].trim());
  }

  return paths;
}

function evaluateToolPermissions(
  tool: string,
  args: Record<string, unknown>,
  config: SandboxConfig,
  baseDirectory: string,
  effectiveAllowRead: string[],
  effectiveAllowWrite: string[],
): SandboxPermissionDecision[] {
  if (tool === 'read') {
    const paths = Array.isArray(args.paths)
      ? args.paths.filter((path): path is string => typeof path === 'string')
      : typeof args.path === 'string'
        ? [args.path]
        : [];
    return paths.map((path) =>
      evaluateReadPermission(path, config, baseDirectory, effectiveAllowRead),
    );
  }

  if (tool === 'glob' || tool === 'grep') {
    const searchPath = typeof args.path === 'string' ? args.path : '.';
    return [evaluateReadPermission(searchPath, config, baseDirectory, effectiveAllowRead)];
  }

  if (tool === 'write' || tool === 'edit') {
    const paths = Array.isArray(args.paths)
      ? args.paths.filter((path): path is string => typeof path === 'string')
      : typeof args.path === 'string'
        ? [args.path]
        : [];
    return paths.map((path) =>
      evaluateWritePermission(path, config, baseDirectory, effectiveAllowWrite),
    );
  }

  if (tool === 'patch' && typeof args.patchText === 'string') {
    return extractPatchPaths(args.patchText).map((path) =>
      evaluateWritePermission(path, config, baseDirectory, effectiveAllowWrite),
    );
  }

  if (tool === 'shell') {
    const commands = Array.isArray(args.commands)
      ? args.commands.filter((command): command is string => typeof command === 'string')
      : typeof args.command === 'string'
        ? [args.command]
        : [];
    return commands.flatMap((command) => evaluateCommandDomains(command, config));
  }
  return [];
}

const plugin: Plugin.Plugin = {
  id: 'opencode-landstrip',
  async setup(context: Plugin.Context) {
    const directory = context.location?.directory ?? process.cwd();
    const configStore = new SandboxConfigStore(directory, normalizeOptions(context.options));
    const discovery = new TrapPortDiscovery(directory);
    const pendingByCommand = new Map<string, { callID: string; sessionID: string | undefined }>();
    const activeBash = new Map<string, BashSandboxState>();
    const callByShellID = new Map<string, string>();
    const exitedShells = new Set<string>();
    const shellEventsAbort = new AbortController();
    const notified = new Set<string>();
    let enabledNotified = false;
    let landstripCheck: { ok: true; version: string } | { ok: false; reason: string } | undefined;
    async function notifyOnce(key: string, message: string, variant: ToastVariant): Promise<void> {
      if (notified.has(key)) return;
      notified.add(key);
      const output =
        variant === 'error' ? console.error : variant === 'warning' ? console.warn : console.info;
      output(`opencode-landstrip: ${message}`);
    }

    function checkLandstrip(): typeof landstripCheck {
      if (landstripCheck) return landstripCheck;

      if (!SUPPORTED_PLATFORMS.has(process.platform)) {
        landstripCheck = {
          ok: false,
          reason: `landstrip sandboxing is not supported on ${process.platform}`,
        };
        return landstripCheck;
      }

      let version: string | null;
      try {
        const result = spawnSync(landstripBinaryPath(), ['--version'], { encoding: 'utf-8' });
        version = result.status === 0 ? result.stdout.trim() : null;
      } catch (error) {
        landstripCheck = {
          ok: false,
          reason: error instanceof Error ? error.message : String(error),
        };
        return landstripCheck;
      }

      if (!version) {
        landstripCheck = {
          ok: false,
          reason: `landstrip was not found. Reinstall with: npm install @landstrip/landstrip-api`,
        };
        return landstripCheck;
      }

      const parsedVersion = parse(
        version.startsWith('landstrip ') ? version.slice('landstrip '.length) : version,
      );
      // Include prereleases at the minimum release, matching the historical release-number gate.
      if (!parsedVersion || !gte(parsedVersion, `${REQUIRED_LANDSTRIP_VERSION}-0`)) {
        landstripCheck = {
          ok: false,
          reason: `landstrip ${REQUIRED_LANDSTRIP_VERSION} or newer is required; found: ${version}`,
        };
        return landstripCheck;
      }

      landstripCheck = { ok: true, version };
      return landstripCheck;
    }

    async function activeConfig(): Promise<SandboxConfig | null> {
      const config = configStore.load();
      if (!config.enabled) {
        await notifyOnce(
          `not-configured:${directory}`,
          'Sandbox is disabled by configuration',
          'info',
        );
        return null;
      }

      const check = checkLandstrip();
      if (!check?.ok) {
        const reason = check?.reason ?? 'Unknown Landstrip installation error';
        await notifyOnce(`broken-installation:${reason}`, reason, 'error');
        throw new Error(`Broken @landstrip/landstrip-api installation: ${reason}`);
      }

      if (!enabledNotified) {
        enabledNotified = true;
        if (config.network.allowNetwork) {
          await notifyOnce(
            'network-allow',
            'Network sandbox is disabled because network.allowNetwork is true.',
            'warning',
          );
        } else {
          const networkLabel = allowsAllDomains(config.network.allowedDomains)
            ? 'all domains'
            : `${config.network.allowedDomains.length} domains`;
          await notifyOnce(
            'enabled',
            `Sandbox enabled: ${networkLabel}, ${config.filesystem.allowWrite.length} write paths`,
            'info',
          );
          if (allowsAllDomains(config.network.allowedDomains)) {
            await notifyOnce(
              'network-all',
              'Network sandbox allows all domains because network.allowedDomains contains "*".',
              'warning',
            );
          }
        }
      }

      return config;
    }

    async function cleanupBash(callID: string): Promise<void> {
      const state = activeBash.get(callID);
      if (!state) return;

      activeBash.delete(callID);
      if (pendingByCommand.get(state.wrappedCommand)?.callID === callID) {
        pendingByCommand.delete(state.wrappedCommand);
      }
      if (state.shellID !== undefined) callByShellID.delete(state.shellID);
      if (state.stop) await state.stop().catch(() => undefined);
      await closeTrapServer(state);
      rmSync(state.policyDir, { recursive: true, force: true });
    }

    async function closeTrapServer(state: BashSandboxState): Promise<void> {
      const server = state.trapServer;
      if (!server) return;
      state.trapServer = null;
      await new Promise<void>((resolve) => {
        server.close(() => resolve());
      });
    }

    async function prepareBash(
      callID: string,
      sessionID: string | undefined,
      args: Record<string, unknown>,
      config: SandboxConfig,
      env?: Record<string, string | undefined>,
      overrideShell?: string,
    ): Promise<void> {
      if (typeof args.command !== 'string') return;
      const normalizedSessionID = sessionID?.trim() || undefined;

      const rewriteDescription = (): void => {
        if (typeof args.description === 'string' && !args.description.endsWith(' (landstrip)')) {
          args.description = `${args.description} (landstrip)`;
        }
      };

      const existing = activeBash.get(callID);
      if (existing) {
        if (
          existing.sessionID === normalizedSessionID &&
          (args.command === existing.originalCommand || args.command === existing.wrappedCommand)
        ) {
          args.command = existing.wrappedCommand;
          rewriteDescription();
          if (env) {
            const envVars = proxyEnv(existing.port, existing.proxyToken);
            if (envVars) Object.assign(env, envVars);
          }
          return;
        }

        await cleanupBash(callID);
      }

      if (isGeneratedWrappedCommand(args.command as string)) {
        if (activeBash.has(callID)) await cleanupBash(callID);
        const original = extractOriginalCommand(args.command as string);
        if (original) args.command = original;
      }

      const allowNetwork = config.network.allowNetwork;
      if (!allowNetwork) {
        for (const decision of evaluateCommandDomains(args.command as string, config)) {
          if (decision.status !== 'allow') throw configStore.errorWithPaths(decision.message);
        }
      }

      const proxyCredentials = allowNetwork ? null : createProxyCredentials();
      const proxyToken = proxyCredentials ? proxyCredentials.token : null;
      const proxy = allowNetwork
        ? null
        : await startFilterProxy({
            isDomainAllowed: (domain) => isDomainAllowed(domain, config.network),
            ...(proxyCredentials ? { authorization: proxyCredentials.authorization } : {}),
          });
      const proxyPort = proxy ? proxy.port : null;
      let policy: { dir: string; path: string };

      try {
        policy = writePolicyFile(config, directory, proxyPort);
      } catch (error) {
        if (proxy) await proxy.stop().catch(() => undefined);
        throw error;
      }

      const originalCommand = args.command as string;

      // The TUI owns interactive query handling. Fall back to an in-process
      // broker when no TUI endpoint or session identity is available.
      const interactiveSessionID = normalizedSessionID ?? '';
      const tuiTrapPort =
        process.platform === 'linux' && interactiveSessionID
          ? await discovery.connectablePort()
          : null;
      const trapServer =
        process.platform !== 'win32' && tuiTrapPort === null
          ? await startTrapServer(
              config.filesystem.allowRead,
              config.filesystem.allowWrite,
              config.filesystem.denyRead,
              config.filesystem.denyWrite,
              directory,
              config.filesystem.denyReadAlways,
              config.filesystem.denyWriteAlways,
            )
          : null;
      const trapPort = tuiTrapPort ?? trapServer?.port ?? null;

      const wrappedCommand = buildWrappedCommand(
        policy.path,
        overrideShell ?? process.env.SHELL ?? '/bin/sh',
        originalCommand,
        trapPort,
        tuiTrapPort === null ? undefined : interactiveSessionID,
      );

      activeBash.set(callID, {
        originalCommand,
        wrappedCommand,
        sessionID: normalizedSessionID,
        policyDir: policy.dir,
        port: proxyPort,
        proxyToken,
        stop: proxy ? proxy.stop : null,
        trapServer: trapServer?.server ?? null,
        trapServerPort: trapPort,
        trapStanzas: trapServer?.trapStanzas ?? [],
        tuiConnected: tuiTrapPort !== null,
      });

      args.command = wrappedCommand;
      rewriteDescription();
      if (env) {
        const envVars = proxyEnv(proxyPort, proxyToken);
        if (envVars) Object.assign(env, envVars);
      }
    }

    context.permission.hook('evaluate', async (evaluation) => {
      if (evaluation.effect === 'deny') return;
      const config = await activeConfig();
      if (!config) return;

      const action = evaluation.action;
      const resources = [...(evaluation.resources ?? [])];
      const effectiveAllowRead = config.filesystem.allowRead;
      const effectiveAllowWrite = config.filesystem.allowWrite;
      const args: Record<string, unknown> = { ...evaluation.metadata };
      if (action === 'read' || action === 'external_directory') args.paths = resources;
      if (action === 'edit') args.paths = resources;
      if (action === 'shell') args.commands = resources;
      const toolName = action === 'external_directory' ? 'read' : action;
      const decisions = evaluateToolPermissions(
        toolName,
        args,
        config,
        directory,
        effectiveAllowRead,
        effectiveAllowWrite,
      );

      const denied = decisions.find((item) => item.status === 'deny');
      if (denied) {
        evaluation.effect = 'deny';
        evaluation.message = denied.message;
        return;
      }

      const approvals = decisions.filter((item) => item.status === 'ask');
      if (approvals.length === 0) return;

      evaluation.effect = 'ask';
      evaluation.message = approvals.map((item) => item.message).join('\n');
    });

    context.tool.hook('execute.before', async (event) => {
      const config = await activeConfig();
      if (!config) return;

      const args = isRecord(event.input) ? event.input : {};

      if (event.tool === 'shell') {
        if (typeof args.command === 'string') {
          await prepareBash(event.id, event.sessionID, args, config);
          pendingByCommand.set(args.command, { callID: event.id, sessionID: event.sessionID });
        }
        return;
      }

      const decisions = evaluateToolPermissions(
        event.tool,
        args,
        config,
        directory,
        config.filesystem.allowRead,
        config.filesystem.allowWrite,
      );
      for (const decision of decisions) {
        if (decision.status === 'allow') continue;
        if (decision.status === 'ask' && ['read', 'write', 'edit', 'patch'].includes(event.tool)) {
          // These host tools assert their own permission during execution.
          continue;
        }
        throw configStore.errorWithPaths(decision.message);
      }
    });

    context.shell.hook('create.before', async (invocation) => {
      const config = await activeConfig();
      if (!config) return;

      const pending = pendingByCommand.get(invocation.command);
      const callID = pending?.callID || `shell-${randomBytes(6).toString('hex')}`;
      const sessionID = pending?.sessionID;

      await prepareBash(
        callID,
        sessionID,
        invocation as unknown as Record<string, unknown>,
        config,
        invocation.env,
        invocation.shell,
      );
    });

    function trackShell(callID: string, state: BashSandboxState, shellID: string): void {
      state.shellID = shellID;
      state.shellExited ||= exitedShells.has(shellID);
      if (!state.shellExited) callByShellID.set(shellID, callID);
    }

    const shellEvents = (async () => {
      for await (const event of context.event.subscribe({
        types: ['shell.created', 'shell.exited', 'shell.deleted'],
        signal: shellEventsAbort.signal,
      })) {
        if (event.type === 'shell.created') {
          const { id, command, status } = event.data.info;
          const pending = pendingByCommand.get(command);
          if (!pending) continue;
          const state = activeBash.get(pending.callID);
          pendingByCommand.delete(command);
          if (!state) continue;
          state.shellExited ||= status !== 'running';
          trackShell(pending.callID, state, id);
          continue;
        }

        const { id } = event.data;
        if (event.type === 'shell.deleted') exitedShells.delete(id);
        else exitedShells.add(id);
        const callID = callByShellID.get(id);
        if (callID === undefined) continue;
        callByShellID.delete(id);
        const state = activeBash.get(callID);
        if (!state) continue;
        state.shellExited = true;
        if (state.background) {
          await finishBash(callID, state, '').catch((error: unknown) => {
            console.error('opencode-landstrip: Background shell cleanup failed:', error);
          });
        }
      }
    })().catch((error: unknown) => {
      if (!shellEventsAbort.signal.aborted) {
        console.error('opencode-landstrip: Shell event subscription failed:', error);
      }
    });

    context.tool.hook('execute.after', async (event) => {
      if (event.tool !== 'shell') return;

      const state = activeBash.get(event.id);
      if (!state) return;

      let outputText = '';
      if (event.status === 'completed') {
        const { output, content } = event.result;
        if (isRecord(output) && output.status === 'running' && typeof output.shellID === 'string') {
          trackShell(event.id, state, output.shellID);
          if (!state.shellExited) {
            state.background = true;
            return;
          }
        }
        if (typeof output === 'string') {
          outputText = output;
        } else if (isRecord(output) && typeof output.output === 'string') {
          outputText = output.output;
        } else if (typeof content === 'string') {
          outputText = content;
        } else if (Array.isArray(content)) {
          outputText = content
            .flatMap((part) =>
              isRecord(part) && part.type === 'text' && typeof part.text === 'string'
                ? [part.text]
                : [],
            )
            .join('\n');
        }
      }
      await finishBash(event.id, state, outputText);
    });

    async function finishBash(
      callID: string,
      state: BashSandboxState,
      outputText: string,
    ): Promise<void> {
      await closeTrapServer(state);
      const trapOutput = state.trapServerPort !== null ? state.trapStanzas.join('') : outputText;
      const traps = parseLandstripTraps(trapOutput).filter(
        (trap: LandstripTrap) => !isQueryTrap(trap),
      );
      if (traps.length > 0) {
        console.error(`opencode-landstrip: ${formatLandstripTraps(traps)}`);
      }

      if (!state.tuiConnected) {
        const blockedTrap = traps.find(isFilesystemTrap);
        const blockedPath = blockedTrap
          ? canonicalizePath(blockedTrap.path, directory)
          : (extractDeniedPath(trapOutput, {
              cwd: directory,
              command: state.originalCommand,
            }) ?? extractNativeDeniedPath(outputText, directory));
        if (blockedPath) {
          const blockedOperation = blockedTrap?.operation ?? 'read';
          await notifyOnce(
            `blocked:${blockedPath}`,
            `Sandbox blocked ${blockedOperation} to "${blockedPath}". No live TUI presenter was available, so access remains denied.`,
            'warning',
          );
        }
      }

      await cleanupBash(callID);
    }

    return async () => {
      shellEventsAbort.abort();
      await shellEvents;
      await Promise.all([...activeBash.keys()].map((callID) => cleanupBash(callID)));
    };
  },
};

export { plugin };
export default plugin;
